  function g(n){ return 0.5*Math.pow(n,1.25)+0.6; }
  function fbase(n){ return 0.4*Math.pow(n,1.2)+0.5; }
  function wig(n){ return 1.2*Math.sin(3*n)*Math.exp(-0.4*n); }
  function f(n){ return fbase(n)+wig(n); }

  var state={ type:'Theta (two-sided)', n0:3, c:1, caption:'f(n) = Θ(g(n))' };

  var fData=ns.map(function(n){return {x:n,y:f(n)};});

  function upperVal(n){
    if(state.type.indexOf('Theta')===0) return 1.3*state.c*g(n);
    if(state.type.indexOf('O')===0) return 1.3*state.c*g(n);
    return NaN;
  }
  function lowerVal(n){
    if(state.type.indexOf('Theta')===0) return 0.6*state.c*g(n);
    if(state.type.indexOf('Omega')===0) return 0.6*state.c*g(n);
    return NaN;
